import openpyxl
wb = openpyxl.load_workbook('output.xlsx')
ws = wb['Sheet1']

totals = []
for r in range(1,4):
    t = sum(ws.cell(row=r, column=c).value for c in range(2,6))
    totals.append(t)

mx = max(totals)
n_max = sum(1 for t in totals if t == mx)

for r in range(5,8):
    for c in range(2,6):
        if totals[r-5] == mx:
            if n_max == 1:
                val = 6
            elif n_max == 2:
                val = 3
            else:
                val = 2
        else:
            val = 0
        ws.cell(row=r, column=c).value = val

wb.save('output.xlsx')
print("done")
EOF
python3 solve.py
